const listStoppableGoalCheckpointKeys = `-- name: ListStoppableGoalCheckpointKeys :many
SELECT generation, node_id, item_index
FROM loop_goal_checkpoints
WHERE loop_run_id = ?1 AND phase != 'terminal'
ORDER BY generation ASC, node_id ASC, item_index ASC
`

type ListStoppableGoalCheckpointKeysRow struct {
	Generation int64  `json:"generation"`
	NodeID     string `json:"node_id"`
	ItemIndex  int64  `json:"item_index"`
}

func (q *Queries) ListStoppableGoalCheckpointKeys(ctx context.Context, loopRunID string) ([]ListStoppableGoalCheckpointKeysRow, error) {
	rows, err := q.db.QueryContext(ctx, listStoppableGoalCheckpointKeys, loopRunID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListStoppableGoalCheckpointKeysRow{}
	for rows.Next() {
		var i ListStoppableGoalCheckpointKeysRow
		if err := rows.Scan(&i.Generation, &i.NodeID, &i.ItemIndex); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

